update info_safe_user
set safe_company_id = #{safeCompanyId,jdbcType=BIGINT},
  user_id = #{userId,jdbcType=BIGINT}
where id = #{id,jdbcType=BIGINT}

mapper.select:
select

from info_safe_user


        and safe_company_id = #{safeCompanyId,jdbcType=BIGINT}


        and user_id = #{userId,jdbcType=BIGINT}

select a.user_name as userName, a.user_tel as userTel, a.nick_name as nickName, a.org_name as orgName, a.sex as sex, b.id as infoSafeUserId from user_info a left join info_safe_user b on a.user_id = b.user_id
and a.user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
and a.user_tel like CONCAT(CONCAT('%',#{userTel,jdbcType=VARCHAR}), '%')
and b.safe_company_id = #{safeCompanyId,jdbcType=BIGINT}
ORDER BY b.user_id desc limit #{pageIndex} , #{pageSize}
